define({"topics":[{"title":"Installing SEMS software","shortdesc":"<p class=\"shortdesc\">When setting up the transmitter (Tx) and receiver (Rx) from the coherent noise tool kit for measurement, if frequencies are not correct, you can enter frequencies using the SEMS software. This procedure gives steps for installing the SEMS software.<\/p>","href":"t_InstallingSEMSSoftware.html","attributes":{"data-id":"id_2045891"},"menu":{"hasChildren":false},"tocID":"id_2045891-d46e80141","topics":[]},{"title":"Entering frequencies using SEMS software","shortdesc":"<p class=\"shortdesc\">When setting up the transmitter (Tx) and receiver (Rx) from the coherent noise tool kit for measurement, if frequencies are not correct, you can enter frequencies using the SEMS software.<\/p>","href":"t_EnteringFrequenciesUsingSEMSSoftware.html","attributes":{"data-id":"id_2045892"},"menu":{"hasChildren":false},"tocID":"id_2045892-d46e80246","topics":[]}]});